  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Direct absolute oral bioavailability in normal subjects was 29.9 ± 1.7% for labetalol, above the 20% threshold."
    },
    {
      "card_ids": ["C25"],
      "claim": "Terodiline showed a mean absolute oral bioavailability of 92% after a 12.5 mg oral dose in healthy volunteers, well above the 20% threshold."
    },
    {
      "card_ids": ["C12"],
      "claim": "Baclofen showed an absolute oral bioavailability of 81.2% after a 20 mg oral dose, well above the 20% threshold."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All high-scoring evidence molecules support oral bioavailability at or above 20%, with direct absolute measurements ranging from about 26% to 92%; therefore predict high.",
  "evidence_gaps": [
    "Some records report bioavailability below 20% (e.g., 18% for labetalol, 17% for aspirin), but these are outweighed by direct absolute measurements in the same molecules.",
    "Molecule 10 includes a record for phenytoin sodium (C27) that is inconsistent with the phenylbutyrate records; it was discounted as a provenance conflict.",
    "Several records use unspecified bioavailability type or measure a metabolite, but direct absolute records are available for the main evidence molecules."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C04", "C25", "C12"],
  "revision_action": "initial",
  "supportive_card_ids": ["C04", "C25", "C12"]
}

